## 7. Spring Data MongoDB Aggregation API

```kotlin
import org.springframework.data.mongodb.core.MongoTemplate
import org.springframework.data.mongodb.core.aggregation.Aggregation.*
import org.springframework.data.mongodb.core.aggregation.AggregationResults
import org.springframework.data.mongodb.repository.Aggregation
import org.springframework.stereotype.Repository

// 방법 1: @Aggregation 어노테이션
@Repository
interface OrderRepository : MongoRepository<Order, String> {

    @Aggregation(pipeline = [
        "{ '\$match': { 'status': 'completed', 'orderDate': { '\$gte': ?0, '\$lt': ?1 } } }",
        "{ '\$group': { '_id': '\$category', 'totalRevenue': { '\$sum': '\$totalAmount' }, 'count': { '\$sum': 1 } } }",
        "{ '\$sort': { 'totalRevenue': -1 } }",
        "{ '\$limit': 10 }"
    ])
    fun findTopCategoriesByRevenue(
        startDate: Instant,
        endDate: Instant
    ): List<CategoryRevenueSummary>
}

data class CategoryRevenueSummary(
    val id: String,           // _id -> category
    val totalRevenue: Long,
    val count: Int
)

// 방법 2: MongoTemplate으로 프로그래밍 방식
@Service
class OrderAnalyticsService(
    private val mongoTemplate: MongoTemplate
) {
    fun calculateDailySalesSummary(date: LocalDate): List<DailySalesSummary> {
        val startOfDay = date.atStartOfDay(ZoneId.of("Asia/Seoul")).toInstant()
        val endOfDay = date.plusDays(1).atStartOfDay(ZoneId.of("Asia/Seoul")).toInstant()

        val aggregation = newAggregation(
            match(
                Criteria.where("orderDate").gte(startOfDay).lt(endOfDay)
                    .and("status").`is`("completed")
            ),
            group("category")
                .sum("totalAmount").`as`("totalRevenue")
                .count().`as`("orderCount")
                .avg("totalAmount").`as`("avgOrderValue"),
            sort(Sort.Direction.DESC, "totalRevenue"),
            merge()
                .intoCollection("daily_sales_summary")
                .on("_id")
                .whenMatched(MergeOperation.WhenDocumentsMatch.replaceDocument())
                .whenNotMatched(MergeOperation.WhenDocumentsNotMatch.insertNewDocument())
                .build()
        )

        return mongoTemplate.aggregate(
            aggregation,
            "orders",
            DailySalesSummary::class.java
        ).mappedResults
    }
}
